@GameTestHolder(ThaumicExploration.ID) @PrefixGameTestTemplate(false)
public final class ParityGameTests {
    static final String T="test/platform";
    static MachineEntity machine(GameTestHelper h,String kind){if(kind.equals("think_tank"))for(BlockPos pos:BlockPos.betweenClosed(new BlockPos(1,1,1),new BlockPos(5,3,5)))h.setBlock(pos,Blocks.AIR);return PortGameTests.place(h,kind,3,2,3);}
    static Player player(GameTestHelper h){return h.makeMockPlayer(net.minecraft.world.level.GameType.SURVIVAL);}
    @GameTest(template=T) public static void urnPrioritizesBurningPlayerOverFillingSpa(GameTestHelper h){
        var m=machine(h,"everfull_urn");h.setBlock(new BlockPos(5,2,3),thaumcraft.registry.ModBlocks.ARCANE_SPA.get());
        MachineEntity.tick(h.getLevel(),m.getBlockPos(),m.getBlockState(),m);
        var p=thaumcraft.test.TestSupport.mockServerPlayer(h);p.setPos(net.minecraft.world.phys.Vec3.atCenterOf(h.absolutePos(new BlockPos(4,2,3))));p.setNoGravity(true);h.getLevel().addNewPlayer(p);p.setRemainingFireTicks(200);
        h.runAfterDelay(65,()->{try{h.assertTrue(!p.isOnFire(),"busy urn failed to prioritize burning player");h.succeed();}finally{h.getLevel().removePlayerImmediately(p,Entity.RemovalReason.DISCARDED);}});
    }
    @GameTest(template=T) public static void beltSetsAndRemovesActualResistanceAttribute(GameTestHelper h){var p=thaumcraft.test.TestSupport.mockServerPlayer(h);var a=p.getAttribute(net.minecraft.world.entity.ai.attributes.Attributes.KNOCKBACK_RESISTANCE);double base=a.getValue();thaumcraft.platform.Baubles.set(p,3,new ItemStack(Content.item("stabilizer_belt")));h.assertTrue(thaumcraft.platform.Baubles.isEquipped(p,Content.item("stabilizer_belt")),"belt setup");net.neoforged.neoforge.common.NeoForge.EVENT_BUS.post(new net.neoforged.neoforge.event.tick.PlayerTickEvent.Post(p));h.assertTrue(a.getValue()>=1,"resistance attribute absent");thaumcraft.platform.Baubles.set(p,3,ItemStack.EMPTY);net.neoforged.neoforge.common.NeoForge.EVENT_BUS.post(new net.neoforged.neoforge.event.tick.PlayerTickEvent.Post(p));h.assertTrue(Math.abs(a.getValue()-base)<0.0001,"resistance remains after unequip");h.succeed();}
    @GameTest(template=T) public static void meteorAcceleratesGraduallyAndCometFreezeHasLegacyRange(GameTestHelper h){var p=player(h);p.setPos(net.minecraft.world.phys.Vec3.atCenterOf(h.absolutePos(new BlockPos(3,2,3))));var boots=new ItemStack(Content.item("meteor_boots"));var data=Data.get(boots);data.putBoolean("IsSmashing",true);data.putInt("airTicks",10);Data.put(boots,data);p.setItemSlot(EquipmentSlot.FEET,boots);p.setOnGround(false);p.setDeltaMovement(0,-0.2,0);net.neoforged.neoforge.common.NeoForge.EVENT_BUS.post(new net.neoforged.neoforge.event.tick.PlayerTickEvent.Post(p));h.assertTrue(Math.abs(p.getDeltaMovement().y+0.3)<0.0001,"smash must add -0.1 each tick");p.setItemSlot(EquipmentSlot.FEET,new ItemStack(Content.item("comet_boots")));var near=p.blockPosition().offset(4,-1,0);var far=p.blockPosition().offset(5,-1,5);h.getLevel().setBlockAndUpdate(near.above(),Blocks.AIR.defaultBlockState());h.getLevel().setBlockAndUpdate(far.above(),Blocks.AIR.defaultBlockState());h.getLevel().setBlockAndUpdate(near,Blocks.WATER.defaultBlockState());h.getLevel().setBlockAndUpdate(far,Blocks.WATER.defaultBlockState());net.neoforged.neoforge.common.NeoForge.EVENT_BUS.post(new net.neoforged.neoforge.event.tick.PlayerTickEvent.Post(p));h.assertTrue(h.getLevel().getBlockState(near).is(Content.MELTY_ICE.get()),"legacy freeze radius missing");h.assertTrue(h.getLevel().getBlockState(far).is(Blocks.WATER),"Manhattan limit ignored");h.succeed();}
    @GameTest(template=T) public static void necromancerOrbsUseHotbarSelectionValueAndCooldown(GameTestHelper h){var p=player(h);var first=Wands.create(WandRegistry.cap("gold"),WandRegistry.rod("greatwood"),false);var necro=Wands.create(WandRegistry.cap("gold"),WandRegistry.rod("NECROMANCER_staff"),false);p.getInventory().setItem(0,first);p.getInventory().setItem(1,necro);var orb=thaumcraft.entity.AspectOrb.create(h.getLevel(),p.getX()+2.8,p.getY(),p.getZ(),Aspect.AIR,1);h.getLevel().addFreshEntity(orb);Magic.necro(necro,p);h.assertTrue(!orb.isAlive(),"orb outside radius two not collected");h.assertValueEqual(Wands.getVis(first,Aspect.AIR),100,"wrong wand or orb multiplier");h.assertValueEqual(Wands.getVis(necro,Aspect.AIR),0,"necro forced as recipient");var other=thaumcraft.entity.AspectOrb.create(h.getLevel(),p.getX(),p.getY(),p.getZ(),Aspect.AIR,1);h.getLevel().addFreshEntity(other);Magic.necro(necro,p);h.assertTrue(other.isAlive(),"player pickup cooldown ignored");other.discard();h.succeed();}
    @GameTest(template=T) public static void taintCharmConsumesFoodThenAppliesWithdrawal(GameTestHelper h){var p=player(h);p.getInventory().setItem(9,new ItemStack(Content.item("taint_charm")));p.getInventory().setItem(0,new ItemStack(Content.tc("tainted_goo")));p.getPersistentData().putInt("tx.taintGrace",100);TaintCharm.tick(p);h.assertTrue(p.getInventory().getItem(0).isEmpty()&&p.getPersistentData().getInt("tx.taintGrace")==0,"tainted food did not reset grace");p.getPersistentData().putInt("tx.taintGrace",100);TaintCharm.tick(p);h.assertTrue(p.hasEffect(Content.WITHDRAWAL),"withdrawal absent outside taint");h.succeed();}
    @GameTest(template=T) public static void taintCharmRemovalRetainsLegacyPenalty(GameTestHelper h){var p=player(h);p.getPersistentData().putBoolean("tx.tainted",true);TaintCharm.tick(p);h.assertTrue(!p.isAlive(),"removing charm must retain original penalty");h.succeed();}
    @GameTest(template=T) public static void recipeIngredientsAndStaffCostMatchLegacyAlternatives(GameTestHelper h){var dream=(ShapedArcaneRecipe)TcRecipes.get("TX:DREAMCATCHER");h.assertTrue(dream.grid().get(6).test(new ItemStack(Content.tc("taint_tendril")))&&dream.grid().get(6).test(new ItemStack(Items.FEATHER)),"official recipe alternatives missing");var staff=(ShapedArcaneRecipe)TcRecipes.get("TX:ROD_TRANSMUTATION_staff");h.assertValueEqual(staff.aspects().getAmount(Aspect.ORDER),18,"staff order cost");h.assertValueEqual(WandRegistry.rod("TRANSMUTATION_staff").craftCost(),18,"registered staff cost");var reg=h.getLevel().registryAccess().lookupOrThrow(Registries.ENCHANTMENT);h.assertValueEqual(reg.getOrThrow(net.minecraft.resources.ResourceKey.create(Registries.ENCHANTMENT,ThaumicExploration.id("disarming"))).value().getMaxLevel(),3,"disarming max level");h.succeed();}
    @GameTest(template=T) public static void namedNetworksPersistAndSeparateStorageTypes(GameTestHelper h){
        var data=new BoundNetworks();UUID a=data.named("jar","Дом"),b=data.named("jar","Дом"),c=data.named("chest","Дом");h.assertTrue(a.equals(b)&&!a.equals(c),"named network selection");data.network(a).add(Aspect.WATER,17);data.network(c).items.setStackInSlot(0,new ItemStack(Items.DIAMOND,4));var restored=BoundNetworks.restore(data.save(new net.minecraft.nbt.CompoundTag(),h.getLevel().registryAccess()),h.getLevel().registryAccess());h.assertTrue(restored.named("jar","Дом").equals(a),"name lost on reload");h.assertValueEqual(restored.network(a).amount,17,"essentia lost");h.assertValueEqual(restored.network(c).items.getStackInSlot(0).getCount(),4,"items lost");h.succeed();
    }
    @GameTest(template=T) public static void namedSealsJoinAndCopySourceColour(GameTestHelper h){
        var p=player(h);for(int x:new int[]{1,5}){var pos=new BlockPos(x,2,2);h.setBlock(pos,thaumcraft.registry.ModBlocks.WARDED_JAR.get());var s=new ItemStack(Content.item("red_jar_seal"));s.set(net.minecraft.core.component.DataComponents.CUSTOM_NAME,net.minecraft.network.chat.Component.literal("Именованная"));PortGameTests.useSeal(h,p,s,pos);}
        MachineEntity a=h.getBlockEntity(new BlockPos(1,2,2)),b=h.getBlockEntity(new BlockPos(5,2,2));h.assertTrue(a.channel.equals(b.channel),"anvil name did not select same channel");var blue=new ItemStack(Content.item("blue_jar_seal"));PortGameTests.useSeal(h,p,blue,new BlockPos(1,2,2));h.assertTrue(p.getInventory().items.stream().anyMatch(s->s.is(Content.item("red_jar_seal"))&&Data.get(s).hasUUID("Channel")),"copy must use source colour");h.succeed();
    }
    @GameTest(template=T) public static void filteredJarCannotBeSealed(GameTestHelper h){var p=player(h);var pos=new BlockPos(3,2,3);h.setBlock(pos,thaumcraft.registry.ModBlocks.WARDED_JAR.get());thaumcraft.essentia.JarBlockEntity jar=h.getBlockEntity(pos);jar.setAspectFilter(Aspect.FIRE);var seal=new ItemStack(Content.item("red_jar_seal"));PortGameTests.useSeal(h,p,seal,pos);h.assertTrue(!seal.isEmpty()&&h.getBlockEntity(pos)==jar,"filtered jar converted");h.succeed();}
    @GameTest(template=T) public static void thinkTankAutomationHasDirectionalTwoSlots(GameTestHelper h){var m=machine(h,"think_tank");h.assertValueEqual(m.itemHandler(Direction.UP).getSlots(),2,"exposed slot count");h.assertTrue(m.itemHandler(Direction.NORTH).insertItem(0,new ItemStack(Items.BOOK),false).is(Items.BOOK),"side insertion");h.assertTrue(m.itemHandler(Direction.UP).insertItem(0,new ItemStack(Items.BOOK),false).isEmpty(),"top insertion");m.local.setStackInSlot(1,new ItemStack(Content.tc("knowledge_fragment")));h.assertTrue(m.itemHandler(Direction.UP).extractItem(1,1,false).isEmpty(),"top extraction");h.assertTrue(!m.itemHandler(Direction.DOWN).extractItem(1,1,false).isEmpty(),"bottom extraction");h.succeed();}
    @GameTest(template=T) public static void thinkTankOuterRingAndWarmup(GameTestHelper h){var m=machine(h,"think_tank");h.setBlock(new BlockPos(3,1,3),Blocks.BOOKSHELF);m.local.setStackInSlot(0,new ItemStack(Items.BOOK,2));h.assertTrue(m.thinkSpace()&&m.space==1,"open outer ring");h.setBlock(new BlockPos(1,2,3),Blocks.STONE);h.assertTrue(m.thinkSpace()&&m.space==0,"outer obstruction should shrink orbit only");h.runAfterDelay(45,()->{h.assertValueEqual(m.warmup,40,"warmup cap");h.assertTrue(m.rotationTicks>=40,"rotation not advancing");h.succeed();});}
    @GameTest(template=T) public static void urnFillsThaumcraftCrucible(GameTestHelper h){machine(h,"everfull_urn");h.setBlock(new BlockPos(5,2,3),thaumcraft.registry.ModBlocks.CRUCIBLE.get());thaumcraft.alchemy.CrucibleBlockEntity c=h.getBlockEntity(new BlockPos(5,2,3));h.succeedWhen(()->h.assertTrue(c.getWaterAmount()>0,"TC crucible not supplied"));}
    @GameTest(template=T) public static void urnFillsThaumcraftSpa(GameTestHelper h){machine(h,"everfull_urn");h.setBlock(new BlockPos(5,2,3),thaumcraft.registry.ModBlocks.ARCANE_SPA.get());thaumcraft.device.ArcaneSpaBlockEntity spa=h.getBlockEntity(new BlockPos(5,2,3));h.succeedWhen(()->h.assertTrue(spa.getTank().getAmount()>0,"spa not supplied"));}
    @GameTest(template=T) public static void coveredUrnDoesNotFill(GameTestHelper h){machine(h,"everfull_urn");h.setBlock(new BlockPos(3,3,3),Blocks.STONE);h.setBlock(new BlockPos(5,2,3),thaumcraft.registry.ModBlocks.CRUCIBLE.get());h.runAfterDelay(70,()->{thaumcraft.alchemy.CrucibleBlockEntity c=h.getBlockEntity(new BlockPos(5,2,3));h.assertValueEqual(c.getWaterAmount(),0,"covered urn supplied water");h.succeed();});}
    @GameTest(template=T,timeoutTicks=500) public static void replicatorOneCycleAndGhostSurviveReload(GameTestHelper h){var m=machine(h,"replicator");m.template=new ItemStack(Items.STONE);var src=PortGameTests.place(h,"crucible_of_souls",5,2,3);var aspects=AspectHelper.getBonusTags(m.template);src.setAspects(aspects);m.startReplication();var tag=m.saveWithFullMetadata(h.getLevel().registryAccess());m.loadWithComponents(tag,h.getLevel().registryAccess());h.assertTrue(m.replicationRunning&&m.template.is(Items.STONE)&&m.local.getStackInSlot(0).isEmpty(),"ghost lost or physical item created");h.succeedWhen(()->{h.assertValueEqual(m.local.getStackInSlot(1).getCount(),1,"single result missing");h.assertTrue(!m.replicationRunning,"cycle restarted automatically");h.assertTrue(src.getAspects().isEmpty(),"essentia payment incorrect");});}
    @GameTest(template=T) public static void replicatorCannotWorkUnderSolidBlock(GameTestHelper h){var m=machine(h,"replicator");m.template=new ItemStack(Items.STONE);h.setBlock(new BlockPos(3,3,3),Blocks.STONE);m.startReplication();h.assertTrue(!m.replicationRunning,"covered replicator started");h.succeed();}
    @GameTest(template=T) public static void oldReplicatorSampleRefundsOnce(GameTestHelper h){var m=machine(h,"replicator");m.local.setStackInSlot(0,new ItemStack(Items.STONE,2));var tag=m.saveWithFullMetadata(h.getLevel().registryAccess());tag.remove("Template");m.loadWithComponents(tag,h.getLevel().registryAccess());var p=player(h);m.interact(p,net.minecraft.world.InteractionHand.MAIN_HAND);h.assertTrue(m.local.getStackInSlot(0).isEmpty(),"owned sample not refunded");int first=p.getInventory().countItem(Items.STONE);m.interact(p,net.minecraft.world.InteractionHand.MAIN_HAND);h.assertValueEqual(first,2,"sample count changed");h.assertValueEqual(p.getInventory().countItem(Items.STONE),2,"ghost duplicated");h.succeed();}
    @GameTest(template=T) public static void soulCrucibleKillsWithoutItemDropsAndSpillsFlux(GameTestHelper h){var m=machine(h,"crucible_of_souls");var mob=h.spawn(EntityType.ZOMBIE,new BlockPos(4,2,3));mob.setNoAi(true);mob.setHealth(1);/* Keep sunlight from killing the fixture before the first soul tick. */mob.setItemSlot(EquipmentSlot.HEAD,new ItemStack(Items.CARVED_PUMPKIN));mob.setDropChance(EquipmentSlot.HEAD,1);mob.setItemSlot(EquipmentSlot.MAINHAND,new ItemStack(Items.DIAMOND));mob.setDropChance(EquipmentSlot.MAINHAND,1);m.flux=1.8F;MachineEntity.tick(h.getLevel(),m.getBlockPos(),m.getBlockState(),m);var spilled=h.getBlockState(new BlockPos(3,3,3));h.assertTrue(spilled.is(thaumcraft.registry.ModBlocks.FLUX_GAS.get())||spilled.is(thaumcraft.registry.ModBlocks.FLUX_GOO.get()),"flux did not spill");h.runAfterDelay(20,()->{h.assertTrue(!mob.isAlive(),"victim alive");h.assertTrue(h.getLevel().getEntitiesOfClass(net.minecraft.world.entity.item.ItemEntity.class,mob.getBoundingBox().inflate(2)).isEmpty(),"victim dropped items");h.succeed();});}
    @GameTest(template=T) public static void soulCrucibleRetainsPrimalAndLargeStorage(GameTestHelper h){var m=machine(h,"crucible_of_souls");m.setAspects(new AspectList().add(Aspect.AIR,300));h.assertTrue(m.takeFromContainer(Aspect.AIR,10),"remote essentia source cannot drain");h.assertValueEqual(m.containerContains(Aspect.AIR),290,"storage capped");h.assertTrue(!m.canOutputTo(Direction.UP)&&m.canOutputTo(Direction.NORTH),"wrong pipe sides");h.succeed();}
    @GameTest(template=T) public static void lavaUrnIsVisRelay(GameTestHelper h){var m=machine(h,"everburn_urn");h.assertTrue(m instanceof thaumcraft.vis.VisNode&&m.getRange()==8&&!m.isSource(),"urn is not a relay");h.assertValueEqual(m.lava.getTankCapacity(0),4000,"consistent capacity");h.succeed();}
    @GameTest(template=T) public static void transmutationIncludesExactNinetyPercent(GameTestHelper h){var p=player(h);var wand=Wands.create(WandRegistry.cap("gold"),WandRegistry.rod("TRANSMUTATION"),false);for(var a:Aspect.getPrimalAspects())Wands.storeVis(wand,a,6750);Wands.storeVis(wand,Aspect.FIRE,7500);Magic.transmute(wand,p);h.assertValueEqual(Wands.getVis(wand,Aspect.AIR),6787,"90 percent aspect excluded");h.assertValueEqual(Wands.getVis(wand,Aspect.FIRE),6751,"legacy rounding changed");h.succeed();}
    @GameTest(template=T) public static void necromancerWithersMeleeVictim(GameTestHelper h){var p=thaumcraft.test.TestSupport.mockServerPlayer(h);p.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,Wands.create(WandRegistry.cap("gold"),WandRegistry.rod("NECROMANCER_staff"),false));var z=h.spawn(EntityType.ZOMBIE,new BlockPos(3,2,3));z.hurt(h.getLevel().damageSources().playerAttack(p),1);var effect=z.getEffect(net.minecraft.world.effect.MobEffects.WITHER);h.assertTrue(effect!=null&&effect.getDuration()==100,"necro wither missing");h.succeed();}
    @GameTest(template=T) public static void enchantmentsRejectLegacyConflicts(GameTestHelper h){var reg=h.getLevel().registryAccess().lookupOrThrow(Registries.ENCHANTMENT);var binding=reg.getOrThrow(net.minecraft.resources.ResourceKey.create(Registries.ENCHANTMENT,ThaumicExploration.id("binding")));var disarm=reg.getOrThrow(net.minecraft.resources.ResourceKey.create(Registries.ENCHANTMENT,ThaumicExploration.id("disarming")));for(var key:List.of(Enchantments.FIRE_ASPECT,thaumictinkerer.enchanting.TtEnchantments.VAMPIRISM))h.assertTrue(!Enchantment.areCompatible(binding,reg.getOrThrow(key)),"binding conflict allowed");for(var key:List.of(Enchantments.LOOTING,Enchantments.FORTUNE))h.assertTrue(!Enchantment.areCompatible(disarm,reg.getOrThrow(key)),"loot conflict allowed");h.succeed();}
    @GameTest(template=T) public static void dreamcatcherProtectsTaintButNotGenericMagic(GameTestHelper h){var p=player(h);p.getInventory().setItem(9,new ItemStack(Content.item("dreamcatcher")));int prevented=0;p.getRandom().setSeed(318);for(int i=0;i<40;i++){p.invulnerableTime=0;p.setHealth(20);if(!p.hurt(h.getLevel().damageSources().source(thaumcraft.damage.ModDamageTypes.TAINT),1))prevented++;}h.assertTrue(prevented>15&&prevented<40,"75 percent protection absent or unconditional");p.invulnerableTime=0;h.assertTrue(p.hurt(h.getLevel().damageSources().magic(),1),"unrelated magic canceled");h.succeed();}
    @GameTest(template=T) public static void cometRunCounterLivesOnBoots(GameTestHelper h){var p=player(h);var boots=new ItemStack(Content.item("comet_boots"));p.setItemSlot(EquipmentSlot.FEET,boots);p.setOnGround(true);p.setDeltaMovement(0.2,0,0);ElementalMovement.tick(p,false);h.assertValueEqual(Data.get(boots).getInt("runTicks"),1,"actual motion did not accelerate");p.setDeltaMovement(0,0,0);ElementalMovement.tick(p,true);h.assertValueEqual(Data.get(boots).getInt("runTicks"),0,"stationary grounded player accelerated");h.succeed();}
    @GameTest(template=T) public static void cometIceMeltsToWater(GameTestHelper h){var pos=new BlockPos(3,2,3);h.setBlock(pos,Content.MELTY_ICE.get());Content.MELTY_ICE.get().randomTick(h.getBlockState(pos),h.getLevel(),h.absolutePos(pos),h.getLevel().random);h.assertTrue(h.getBlockState(pos).is(Blocks.WATER),"melting ice did not restore water");h.succeed();}
    @GameTest(template=T) public static void sorterTransfersOnlyMatchingItemsAndPersistsLinks(GameTestHelper h){var m=machine(h,"auto_sorter");BlockPos from=new BlockPos(1,2,1),to=new BlockPos(5,2,5);h.setBlock(from,Blocks.CHEST);h.setBlock(to,Blocks.CHEST);net.minecraft.world.level.block.entity.ChestBlockEntity input=h.getBlockEntity(from),output=h.getBlockEntity(to);input.setItem(0,new ItemStack(Items.DIAMOND,3));input.setItem(1,new ItemStack(Items.DIRT,5));SorterLinks.Link a=m.sorter.link(h.absolutePos(from),Direction.UP),b=m.sorter.link(h.absolutePos(to),Direction.UP);a.mode=1;b.mode=2;b.filter.setStackInSlot(0,new ItemStack(Items.DIAMOND));var tag=m.saveWithFullMetadata(h.getLevel().registryAccess());m.loadWithComponents(tag,h.getLevel().registryAccess());m.sorter.tick();h.assertValueEqual(output.getItem(0).getCount(),1,"remote transfer missing");h.assertValueEqual(input.getItem(0).getCount(),2,"source lost wrong amount");h.assertValueEqual(input.getItem(1).getCount(),5,"filter ignored");h.assertValueEqual(m.sorter.links.size(),2,"links lost on reload");h.succeed();}
    @GameTest(template=T) public static void sorterFullDestinationNeverDeletesItems(GameTestHelper h){var m=machine(h,"auto_sorter");BlockPos from=new BlockPos(1,2,1),to=new BlockPos(5,2,5);h.setBlock(from,Blocks.CHEST);h.setBlock(to,Blocks.CHEST);net.minecraft.world.level.block.entity.ChestBlockEntity input=h.getBlockEntity(from),out=h.getBlockEntity(to);input.setItem(0,new ItemStack(Items.DIAMOND,3));for(int i=0;i<27;i++)out.setItem(i,new ItemStack(Items.COBBLESTONE,64));m.sorter.link(h.absolutePos(from),Direction.UP).mode=1;m.sorter.link(h.absolutePos(to),Direction.UP).mode=2;m.sorter.tick();h.assertValueEqual(input.getItem(0).getCount(),3,"items deleted by full target");h.succeed();}
    @GameTest(template=T) public static void sorterFiltersAreGhosts(GameTestHelper h){var p=player(h);var filters=new net.minecraft.world.SimpleContainer(18);var menu=new SorterMenu(1,p.getInventory(),filters,new net.minecraft.world.inventory.SimpleContainerData(1));menu.setCarried(new ItemStack(Items.DIAMOND,8));menu.clicked(0,0,net.minecraft.world.inventory.ClickType.PICKUP,p);h.assertValueEqual(menu.getCarried().getCount(),8,"filter consumed cursor item");h.assertValueEqual(filters.getItem(0).getCount(),1,"filter size");menu.clicked(0,1,net.minecraft.world.inventory.ClickType.PICKUP,p);h.assertTrue(filters.getItem(0).isEmpty(),"filter not cleared");h.succeed();}
    @GameTest(template=T) public static void foodCharmItemsDoNotEquipAsBaubles(GameTestHelper h){var p=player(h);for(String name:List.of("dreamcatcher","talisman_of_nourishment")){var item=(Trinket)Content.item(name);h.assertTrue(!item.canEquip(new ItemStack(item),p),"inventory item accepted as bauble");}h.assertTrue(!CreativeOrder.items().contains("bread_rod"),"disabled easter egg shown");h.assertTrue(CreativeOrder.items().contains("auto_sorter")&&CreativeOrder.items().contains("taint_charm"),"original creative entries missing");h.succeed();}
}


